        const item = this.findInventoryItem(actor, itemId);
        if (!item) {
          return {
            message: `${actor.name} cannot find item '${itemId}'.`,
            warnings: ["item_missing"],
            traitDelta: {},
            featureDelta: {},
            metadata: { itemId },
            foundItemTags: []
          };
        }
