  var UI_STATE_STORAGE_KEY = "dungeonbreak:kaplay:ui-state:v1";
  function initialUiState() {
    return {
      dialogue: {
        sequence: 0,
        steps: []
      },
      fog: {
        radius: 1,
        levelFactor: 0,
        comprehensionFactor: 0,
        awarenessFactor: 0
      }
    };
  }
  function createUiStateStore() {
    let state = initialUiState();
    const persist = () => {
      if (typeof window === "undefined") return;
      try {
        window.localStorage.setItem(UI_STATE_STORAGE_KEY, JSON.stringify(state));
      } catch {
      }
    };
    const hydrate = () => {
      if (typeof window === "undefined") return;
      try {
        const raw = window.localStorage.getItem(UI_STATE_STORAGE_KEY);
        if (!raw) return;
        const parsed = JSON.parse(raw);
        state = {
          ...state,
          ...parsed,
          dialogue: {
            ...state.dialogue,
            ...parsed.dialogue ?? {},
            steps: parsed.dialogue?.steps ?? state.dialogue.steps
          },
          fog: {
            ...state.fog,
            ...parsed.fog ?? {}
          }
        };
      } catch {
      }
    };
    return {
      getState() {
        return state;
      },
      hydrate,
      setFogFromStatus(status) {
        state = {
          ...state,
          fog: formulaRegistry.fogMetrics(status)
        };
        persist();
      },
      recordDialogueStep(action, turn, label) {
        if (action.kind !== "player") return;
        if (action.playerAction.actionType !== "talk" && action.playerAction.actionType !== "choose_dialogue") return;
        state = {
          ...state,
          dialogue: {
            sequence: state.dialogue.sequence + 1,
            steps: [
              ...state.dialogue.steps,
              {
                turn,
                kind: action.playerAction.actionType,
                optionId: action.playerAction.actionType === ACTION_TYPE.CHOOSE_DIALOGUE ? String(action.playerAction.payload.optionId ?? "") : void 0,
                label
              }
            ].slice(-20)
          }
        };
        persist();
      }
    };
  }

